package ru.truetv.launcher;

import android.app.*;
import android.content.*;
import android.content.pm.*;
import android.graphics.Typeface;
import android.os.*;
import android.text.*;
import android.view.*;
import android.widget.*;
import java.util.*;
import java.util.concurrent.*;

/** One on-demand chooser for public system Wi-Fi/Bluetooth screens; only explicit tests can be saved. */
public final class RadioScreens extends Activity {
 private static final String WIFI="wifi";
 private static final ExecutorService worker=Executors.newSingleThreadExecutor();
 private String appearance,pending,confirm,selectedKey;private boolean wifi,full,loading=true,left,restorePending;private int first,firstTop,selectedTop;
 private final ArrayList<Route> all=new ArrayList<>(),shown=new ArrayList<>();private EditText search;private Button mode;private ListView list;private TextView count;private ActionSheet prompt;private final Handler main=new Handler(Looper.getMainLooper());
 static final class Route {final String title,key;final Intent intent;final int score;Route(String t,Intent i,int s){title=t;intent=i;key=i.toUri(0);score=s;}String search(){return title+" "+intent.getComponent()+" "+intent.getAction();}}
 static String key(boolean wifi){return wifi?"wifi_route":"bluetooth_route";}
 private static String label(boolean wifi){return wifi?"Wi-Fi":"Bluetooth";}
 static void testCaptured(Activity a,boolean wifi,Intent candidate){a.startActivity(new Intent(a,RadioScreens.class).putExtra(WIFI,wifi).putExtra("captured_route",candidate.toUri(0)));}
 public static void configure(Activity a,boolean wifi){a.startActivity(new Intent(a,RadioScreens.class).putExtra(WIFI,wifi));}
 public static void open(Activity a,boolean wifi){String saved=new SettingsStore(a).text(key(wifi),"");if(!saved.isEmpty())try{Intent intent=Intent.parseUri(saved,0);if(valid(a,intent)&&Ui.launch(a,intent))return;}catch(Exception ignored){}configure(a,wifi);}
 static boolean valid(Context c,Intent i){try{return i.getComponent()!=null&&accessible(c,c.getPackageManager().getActivityInfo(i.getComponent(),0));}catch(Exception ignored){return false;}}
 private static boolean accessible(Context c,ActivityInfo a){return a.enabled&&a.applicationInfo.enabled&&a.exported&&(a.applicationInfo.flags&ApplicationInfo.FLAG_SYSTEM)!=0&&(a.permission==null||c.checkCallingOrSelfPermission(a.permission)==PackageManager.PERMISSION_GRANTED);}
 protected void onCreate(Bundle state){appearance=Ui.prepare(this);super.onCreate(state);Ui.bars(this);wifi=state!=null?state.getBoolean(WIFI):getIntent().getBooleanExtra(WIFI,false);full=state!=null&&state.getBoolean("all");if(state!=null){pending=state.getString("pending");confirm=state.getString("confirm");left=state.getBoolean("left");selectedKey=state.getString("selected_key");selectedTop=state.getInt("selected_top");first=state.getInt("first");firstTop=state.getInt("first_top");}
  LinearLayout root=new LinearLayout(this);root.setOrientation(1);root.setPadding(Ui.dp(this,24),Ui.dp(this,16),Ui.dp(this,24),Ui.dp(this,16));Ui.backdrop(this,root);setContentView(root);root.addView(Ui.label(this,Ui.word(this,"Выбор экрана ","Choose ")+label(wifi),22));
  TextView help=Ui.label(this,Ui.word(this,"Выберите и проверьте экран. Или нажмите «Запомнить экран», откройте нужный раздел и нажмите «Назад». Сохранение — после проверки.","Choose and test a screen. Or use Capture screen, navigate to the required menu and press Back. Save only after testing."),15);help.setPadding(0,Ui.dp(this,6),0,Ui.dp(this,6));root.addView(help);
  LinearLayout bar=new LinearLayout(this);bar.setGravity(Gravity.CENTER_VERTICAL);search=new EditText(this);search.setSingleLine();search.setTextColor(Ui.ink(this));search.setTextSize(18);search.setHintTextColor(Ui.muted(this));search.setHint(Ui.word(this,wifi?"Поиск: Wi-Fi, сеть, network…":"Поиск: Bluetooth, пульт, accessories…",wifi?"Search: Wi-Fi, network…":"Search: Bluetooth, remote, accessories…"));if(state!=null)search.setText(state.getString("query",""));bar.addView(search,new LinearLayout.LayoutParams(0,Ui.dp(this,52),1));mode=Ui.tvButton(this,"");mode.setId(View.generateViewId());bar.addView(mode,new LinearLayout.LayoutParams(-2,Ui.dp(this,52)));Button learn=Ui.tvButton(this,Ui.word(this,"Запомнить экран","Capture screen"));learn.setId(View.generateViewId());LinearLayout.LayoutParams learnParams=new LinearLayout.LayoutParams(-2,Ui.dp(this,52));learnParams.leftMargin=Ui.dp(this,8);bar.addView(learn,learnParams);learn.setOnClickListener(v->ScreenLearning.start(this,wifi));root.addView(bar);count=Ui.label(this,"…",13);root.addView(count);
  list=new ListView(this);list.setCacheColorHint(android.graphics.Color.TRANSPARENT);list.setDividerHeight(Ui.dp(this,1));list.setSelector(Ui.selector(this));if(Build.VERSION.SDK_INT>=26)list.setDefaultFocusHighlightEnabled(false);list.setAdapter(new BaseAdapter(){public int getCount(){return shown.size();}public Object getItem(int p){return shown.get(p);}public long getItemId(int p){return p;}public View getView(int p,View reuse,ViewGroup parent){TextView row=reuse instanceof TextView?(TextView)reuse:Ui.label(RadioScreens.this,"",16);Route r=shown.get(p);boolean saved=r.key.equals(new SettingsStore(RadioScreens.this).text(key(wifi),""));row.setText(r.title+"\n"+r.intent.getComponent().getClassName()+(r.intent.getAction()==null?"":"\n"+r.intent.getAction()));row.setTextColor(saved?Ui.accent(RadioScreens.this):Ui.ink(RadioScreens.this));row.setTypeface(null,saved?Typeface.BOLD:Typeface.NORMAL);row.setPadding(Ui.dp(RadioScreens.this,12),Ui.dp(RadioScreens.this,10),Ui.dp(RadioScreens.this,12),Ui.dp(RadioScreens.this,10));row.setMinHeight(Ui.dp(RadioScreens.this,60));return row;}});root.addView(list,new LinearLayout.LayoutParams(-1,0,1));
  LinearLayout bottom=new LinearLayout(this);Button reset=Ui.tvButton(this,Ui.word(this,"Сбросить переход","Reset route"));reset.setOnClickListener(v->{capture();new SettingsStore(this).data.edit().remove(key(wifi)).apply();((BaseAdapter)list.getAdapter()).notifyDataSetChanged();queueRestore();});bottom.addView(reset,new LinearLayout.LayoutParams(0,-2,1));Button close=Ui.tvButton(this,Ui.word(this,"Закрыть","Close"));close.setOnClickListener(v->finish());bottom.addView(close,new LinearLayout.LayoutParams(0,-2,1));root.addView(bottom);
  mode.setOnClickListener(v->{full=!full;resetPosition();filter();list.setSelectionFromTop(0,0);});search.addTextChangedListener(new TextWatcher(){public void beforeTextChanged(CharSequence s,int st,int n,int a){}public void onTextChanged(CharSequence s,int st,int before,int count){resetPosition();filter();list.setSelectionFromTop(0,0);}public void afterTextChanged(Editable e){}});
  list.setOnItemClickListener((parent,v,pos,id)->{Route route=shown.get(pos);capture();selectedKey=route.key;selectedTop=v.getTop()-list.getPaddingTop();tryRoute(route);});
  getWindow().setSoftInputMode(WindowManager.LayoutParams.SOFT_INPUT_STATE_ALWAYS_HIDDEN);String capturedUri=getIntent().getStringExtra("captured_route");if(capturedUri!=null)try{Intent intent=Intent.parseUri(capturedUri,0);if(valid(this,intent)){captured=new Route(Ui.word(this,"Запомненный экран ","Captured ")+label(wifi),intent,150);all.add(captured);Intent plain=new Intent().setComponent(intent.getComponent());Route alternative=new Route(Ui.word(this,"Запомненный экран · обычный запуск","Captured screen · plain launch"),plain,145);if(!alternative.key.equals(captured.key))all.add(alternative);if(state==null){selectedKey=captured.key;deferredTest=captured;}}}catch(Exception ignored){}
  worker.execute(()->{ArrayList<Route> found=discover(this,wifi);main.post(()->{if(isFinishing()||isDestroyed())return;for(Route route:found){boolean duplicate=false;for(Route previous:all)if(previous.key.equals(route.key)){duplicate=true;break;}if(!duplicate)all.add(route);}loading=false;filter();if(selectedKey!=null)queueRestore();else list.setSelectionFromTop(first,firstTop);});});filter();
 }
 private Route deferredTest,captured;
 private void tryRoute(Route route){if(valid(this,route.intent)&&Ui.launch(this,route.intent)){pending=route.key;left=false;}else{Ui.toast(this,"Этот экран недоступен. Выберите другой.","This screen is unavailable. Choose another.");queueRestore();}}
 private void capture(){first=list.getFirstVisiblePosition();View top=list.getChildAt(0);firstTop=top==null?0:top.getTop()-list.getPaddingTop();if(list.hasFocus()){int pos=list.getSelectedItemPosition();View selected=list.getSelectedView();if(pos>=0&&pos<shown.size()&&selected!=null){selectedKey=shown.get(pos).key;selectedTop=selected.getTop()-list.getPaddingTop();}}}
 private void resetPosition(){selectedKey=null;selectedTop=first=firstTop=0;}
 private void queueRestore(){restorePending=true;list.post(this::restoreSelection);}
 private void restoreSelection(){if(!restorePending||loading||isFinishing()||isDestroyed()||!hasWindowFocus())return;restorePending=false;int index=-1;for(int n=0;n<shown.size();n++)if(shown.get(n).key.equals(selectedKey)){index=n;break;}list.requestFocusFromTouch();if(index>=0)list.setSelectionFromTop(index,selectedTop);else if(!shown.isEmpty())list.setSelectionFromTop(Math.min(first,shown.size()-1),firstTop);}
 public void onWindowFocusChanged(boolean focused){super.onWindowFocusChanged(focused);if(focused&&deferredTest!=null){Route route=deferredTest;deferredTest=null;list.post(()->tryRoute(route));}else if(focused&&restorePending)list.post(this::restoreSelection);}
 private void filter(){if(list==null)return;shown.clear();String q=search.getText().toString();for(Route r:all)if((full||r.score>0)&&Choices.matches(r.search(),q))shown.add(r);((BaseAdapter)list.getAdapter()).notifyDataSetChanged();mode.setText(Ui.word(this,full?"Рекомендации":"Показать всё",full?"Recommended":"Show all"));count.setText(loading?Ui.word(this,"Поиск экранов…","Finding screens…"):Ui.word(this,"Найдено: ","Found: ")+shown.size());}
 private static int score(String s,boolean wifi){String n=Choices.searchable(s);if(wifi){if(n.contains("wifi")||n.contains("wi-fi")||n.contains("wlan"))return 100;return n.contains("network")||n.contains("wireless")||n.contains("сеть")||n.contains("сети")||n.contains("сетев")||n.contains("беспровод")?70:0;}return n.contains("addaccessory")?100:n.contains("bluetooth")||n.contains("блютуз")?90:n.contains("accessor")||n.contains("remote")||n.contains("пульт")||n.contains("аксессуар")?70:n.contains("connect")||n.contains("pair")||n.contains("подключ")?40:0;}
 private static ArrayList<Route> discover(Context c,boolean wifi){PackageManager pm=c.getPackageManager();LinkedHashMap<String,Route> unique=new LinkedHashMap<>();String[] actions=wifi?new String[]{"android.settings.WIFI_SETTINGS","android.settings.WIRELESS_SETTINGS","android.settings.WIFI_IP_SETTINGS","android.settings.panel.action.WIFI","android.settings.panel.action.INTERNET_CONNECTIVITY"}:new String[]{"com.google.android.intent.action.CONNECT_INPUT","android.settings.BLUETOOTH_SETTINGS","android.settings.BLUETOOTH_PAIRING_SETTINGS","android.settings.CONNECTED_DEVICE_SETTINGS","android.bluetooth.devicepicker.action.LAUNCH"};
  for(String action:actions)try{for(ResolveInfo r:pm.queryIntentActivities(new Intent(action),0)){if(accessible(c,r.activityInfo)){Intent i=new Intent(action).setComponent(new ComponentName(r.activityInfo.packageName,r.activityInfo.name));Route route=new Route(String.valueOf(r.loadLabel(pm)),i,120);unique.put(route.key,route);}}}catch(RuntimeException ignored){}
  try{for(ResolveInfo r:pm.queryIntentActivities(new Intent(Intent.ACTION_MAIN).addCategory("android.intent.category.LEANBACK_SETTINGS"),0)){if(accessible(c,r.activityInfo)){Intent intent=new Intent(Intent.ACTION_MAIN).addCategory("android.intent.category.LEANBACK_SETTINGS").setComponent(new ComponentName(r.activityInfo.packageName,r.activityInfo.name));Route route=new Route(String.valueOf(r.loadLabel(pm)),intent,Math.max(10,score(r.activityInfo.name+" "+r.loadLabel(pm),wifi)));unique.put(route.key,route);addHostRoute(c,unique,r.activityInfo,wifi);}}}catch(RuntimeException ignored){}
  for(ApplicationInfo app:pm.getInstalledApplications(0)){if((app.flags&ApplicationInfo.FLAG_SYSTEM)==0)continue;String pkg=app.packageName.toLowerCase(Locale.ROOT);if(!pkg.contains("setting")&&!(wifi?(pkg.contains("wifi")||pkg.contains("wlan")||pkg.contains("network")):(pkg.contains("bluetooth")||pkg.contains("accessor"))))continue;try{PackageInfo info=pm.getPackageInfo(app.packageName,PackageManager.GET_ACTIVITIES);if(info.activities==null)continue;for(ActivityInfo a:info.activities){if(!accessible(c,a))continue;String title=String.valueOf(a.loadLabel(pm));Route route=new Route(title,new Intent().setComponent(new ComponentName(app.packageName,a.name)),score(a.name+" "+title,wifi));unique.put(route.key,route);if(a.name.endsWith(".MainSettings")||a.name.endsWith(".Settings")||a.name.endsWith(".MainActivity"))addHostRoute(c,unique,a,wifi);}}catch(Exception ignored){}}
  ArrayList<Route> result=new ArrayList<>(unique.values());Collections.sort(result,(a,b)->a.score==b.score?a.search().compareToIgnoreCase(b.search()):Integer.compare(b.score,a.score));return result;
 }
 private static void addHostRoute(Context c,Map<String,Route> routes,ActivityInfo host,boolean wifi){if(!accessible(c,host))return;Intent intent=new Intent(wifi?"android.settings.WIFI_SETTINGS":"android.settings.BLUETOOTH_SETTINGS").setComponent(new ComponentName(host.packageName,host.name));Route route=new Route(Ui.word(c,"Системный раздел ","System section ")+label(wifi)+" · "+host.loadLabel(c.getPackageManager()),intent,80);if(!routes.containsKey(route.key))routes.put(route.key,route);}
 protected void onPause(){super.onPause();if(pending!=null)left=true;}
 protected void onResume(){super.onResume();if(!Ui.appearance(this).equals(appearance)){recreate();return;}Ui.bars(this);if(pending!=null&&left){confirm=pending;pending=null;left=false;}if(confirm!=null&&(prompt==null||!prompt.dialog.isShowing())){final String candidate=confirm;prompt=ActionSheet.show(this,Ui.word(this,"Открылся нужный экран?","Did the correct screen open?"),new ActionSheet.Item(Ui.word(this,"Сохранить переход ","Save route for ")+label(wifi),wifi?"wifi":"bluetooth",()->{new SettingsStore(this).data.edit().putString(key(wifi),candidate).apply();finish();}),new ActionSheet.Item(Ui.word(this,"Выбрать другой","Choose another"),"replace",()->{}));prompt.dialog.setOnDismissListener(d->{confirm=null;queueRestore();});}}
 protected void onSaveInstanceState(Bundle state){capture();super.onSaveInstanceState(state);state.putBoolean(WIFI,wifi);state.putBoolean("all",full);state.putString("query",search.getText().toString());state.putString("pending",pending);state.putString("confirm",confirm);state.putBoolean("left",left);state.putString("selected_key",selectedKey);state.putInt("selected_top",selectedTop);state.putInt("first",first);state.putInt("first_top",firstTop);}
}
